import io
import re
import textwrap
import zipfile
from dataclasses import dataclass
from pathlib import Path
from tempfile import NamedTemporaryFile
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

import viktor as vkt
from viktor import Color
from viktor.views import DataGroup, DataItem, DataResult, DataStatus, TableCell, TableResult


# ----------------------------
# Helpers
# ----------------------------

def _split_csv_like(text: str) -> List[str]:
    if not text:
        return []
    parts = [p.strip() for p in text.split(",")]
    return [p for p in parts if p]


def _safe_str(val) -> str:
    if val is None:
        return ""
    s = str(val)
    return s.strip()


def _has_attr(obj, attr: str) -> bool:
    try:
        getattr(obj, attr)
        return True
    except Exception:
        return False


def _compile_regex(pattern: str, *, case_sensitive: bool) -> Optional[re.Pattern]:
    pattern = (pattern or "").strip()
    if not pattern:
        return None
    flags = 0 if case_sensitive else re.IGNORECASE
    return re.compile(pattern, flags=flags)


@dataclass(frozen=True)
class NamingIssue:
    code: str
    message: str


DEFAULT_NAME_REGEXES: Tuple[str, ...] = (
    r"^\s*unnamed\s*$",
    r"^\s*default\s*$",
    # Revit-like / generic patterns
    r"^\s*[a-zA-Z][a-zA-Z0-9 _\-]*\s*#\s*\d+\s*$",
    # Common discipline-specific patterns
    r"^\s*(wall|door|window|slab|beam|column|pipe|duct|cable|tray|stair|railing)\s*#\s*\d+\s*$",
)


def _read_ifc_bytes(file_obj: vkt.File) -> bytes:
    """Accept .ifc or .ifczip (zip containing an .ifc)."""
    raw = file_obj.getvalue()
    if not raw:
        raise vkt.UserError("Uploaded IFC file is empty.")

    # .ifczip is just a zip in many workflows. Detect zip by signature.
    if raw[:2] == b"PK":
        with zipfile.ZipFile(io.BytesIO(raw)) as zf:
            ifc_names = [n for n in zf.namelist() if n.lower().endswith(".ifc")]
            if not ifc_names:
                raise vkt.UserError("This looks like a ZIP, but it doesn't contain an .ifc file.")
            # Pick the first IFC file.
            return zf.read(ifc_names[0])

    return raw


def _open_ifc_model(ifc_bytes: bytes):
    import ifcopenshell

    tmp_path: Optional[Path] = None
    try:
        with NamedTemporaryFile(suffix=".ifc", delete=False) as tmp:
            tmp.write(ifc_bytes)
            tmp_path = Path(tmp.name)

        return ifcopenshell.open(str(tmp_path))
    finally:
        if tmp_path and tmp_path.exists():
            try:
                tmp_path.unlink(missing_ok=True)
            except Exception:
                # Best-effort cleanup; not critical.
                pass


def _iter_elements(model, scope: str, include_types: bool) -> Iterable:
    """Return IFC entities to check."""
    # The scope names are user-facing. Keep these explicit.
    if scope == "IfcProduct":
        elems = model.by_type("IfcProduct")
    elif scope == "IfcObject":
        elems = model.by_type("IfcObject")
    else:
        elems = model.by_type("IfcRoot")

    if include_types:
        elems = list(elems) + list(model.by_type("IfcTypeObject"))

    # Deduplicate by STEP id (if available)
    seen = set()
    for e in elems:
        try:
            sid = int(e.id())
        except Exception:
            sid = id(e)
        if sid in seen:
            continue
        seen.add(sid)
        yield e


def _get_container_name(element) -> str:
    try:
        import ifcopenshell.util.element

        container = ifcopenshell.util.element.get_container(element)
        return _safe_str(getattr(container, "Name", ""))
    except Exception:
        return ""


def _get_type_name(element) -> str:
    # Prefer util function when available
    try:
        import ifcopenshell.util.element

        typ = ifcopenshell.util.element.get_type(element)
        if typ is not None:
            return _safe_str(getattr(typ, "Name", ""))
    except Exception:
        pass

    # Fallback: scan relationships
    try:
        rels = getattr(element, "IsDefinedBy", None) or []
        for rel in rels:
            if rel.is_a("IfcRelDefinesByType"):
                t = rel.RelatingType
                return _safe_str(getattr(t, "Name", ""))
    except Exception:
        pass

    return ""


def _evaluate_name_and_tag(
    *,
    name: str,
    tag: str,
    forbidden_values: Sequence[str],
    default_regex_user: Optional[re.Pattern],
    required_name_regex: Optional[re.Pattern],
    require_number_in_name: bool,
    check_tag_as_numbering: bool,
    case_sensitive: bool,
) -> List[NamingIssue]:
    issues: List[NamingIssue] = []

    forbidden_set = {v if case_sensitive else v.lower() for v in forbidden_values}

    name_s = name.strip()
    tag_s = tag.strip()

    if not name_s:
        issues.append(NamingIssue("NAME_EMPTY", "Name is empty"))
    else:
        key = name_s if case_sensitive else name_s.lower()
        if key in forbidden_set:
            issues.append(NamingIssue("NAME_FORBIDDEN", "Name is a forbidden/default value"))

        for pat in DEFAULT_NAME_REGEXES:
            rx = re.compile(pat, flags=0 if case_sensitive else re.IGNORECASE)
            if rx.match(name_s):
                issues.append(NamingIssue("NAME_DEFAULT", "Name looks like a default (e.g. 'Wall#1')"))
                break

        if default_regex_user is not None and default_regex_user.match(name_s):
            issues.append(NamingIssue("NAME_DEFAULT_RULE", "Name matches your 'default name' regex"))

        if required_name_regex is not None and not required_name_regex.match(name_s):
            issues.append(NamingIssue("NAME_NOT_MATCHING_PATTERN", "Name does not match required naming pattern"))

        if require_number_in_name and not re.search(r"\d", name_s):
            # Note: this is optional because not every naming standard requires digits.
            issues.append(NamingIssue("NAME_NO_NUMBER", "Name does not contain a number"))

    # Optional: treat Tag as the numbering field (common in many BIM workflows)
    if check_tag_as_numbering:
        if not tag_s:
            issues.append(NamingIssue("TAG_EMPTY", "Tag is empty (often used for numbering)"))
        elif not re.search(r"\d", tag_s):
            issues.append(NamingIssue("TAG_NO_NUMBER", "Tag does not contain a number"))

    return issues


def _analyze_ifc(params) -> Tuple[Dict[str, int], List[Dict]]:
    """Returns (summary_counts, rows)."""
    if not params.model.ifc:
        raise vkt.UserError("Upload an IFC file first.")

    ifc_bytes = _read_ifc_bytes(params.model.ifc.file)
    model = _open_ifc_model(ifc_bytes)

    forbidden_values = _split_csv_like(params.rules.forbidden_values)
    case_sensitive = bool(params.rules.case_sensitive)

    default_user = _compile_regex(params.rules.default_name_regex, case_sensitive=case_sensitive)
    required_name = _compile_regex(params.rules.required_name_regex, case_sensitive=case_sensitive)

    rows: List[Dict] = []

    counts = {
        "checked": 0,
        "flagged": 0,
        "name_empty": 0,
        "name_default": 0,
        "name_forbidden": 0,
        "name_no_number": 0,
        "tag_empty": 0,
        "tag_no_number": 0,
        "type_missing": 0,
    }

    for elem in _iter_elements(model, params.model.scan_scope, params.model.include_types):
        # Skip entities which don't have at least a Name attribute (many relationship entities do).
        if not _has_attr(elem, "Name"):
            continue

        counts["checked"] += 1

        ifc_class = elem.is_a()
        step_id = None
        try:
            step_id = int(elem.id())
        except Exception:
            step_id = None

        global_id = _safe_str(getattr(elem, "GlobalId", ""))
        name = _safe_str(getattr(elem, "Name", ""))
        tag = _safe_str(getattr(elem, "Tag", "")) if _has_attr(elem, "Tag") else ""

        storey = _get_container_name(elem)
        type_name = "" if ifc_class.endswith("Type") else _get_type_name(elem)

        issues = _evaluate_name_and_tag(
            name=name,
            tag=tag,
            forbidden_values=forbidden_values,
            default_regex_user=default_user,
            required_name_regex=required_name,
            require_number_in_name=bool(params.rules.require_number_in_name),
            check_tag_as_numbering=bool(params.rules.check_tag_as_numbering),
            case_sensitive=case_sensitive,
        )

        if not type_name and not ifc_class.endswith("Type"):
            issues.append(NamingIssue("TYPE_MISSING", "No IFC Type assigned (IfcRelDefinesByType)"))

        # Update counters
        issue_codes = {i.code for i in issues}
        if "NAME_EMPTY" in issue_codes:
            counts["name_empty"] += 1
        if "NAME_DEFAULT" in issue_codes or "NAME_DEFAULT_RULE" in issue_codes:
            counts["name_default"] += 1
        if "NAME_FORBIDDEN" in issue_codes:
            counts["name_forbidden"] += 1
        if "NAME_NO_NUMBER" in issue_codes:
            counts["name_no_number"] += 1
        if "TAG_EMPTY" in issue_codes:
            counts["tag_empty"] += 1
        if "TAG_NO_NUMBER" in issue_codes:
            counts["tag_no_number"] += 1
        if "TYPE_MISSING" in issue_codes:
            counts["type_missing"] += 1

        if issues:
            counts["flagged"] += 1

        rows.append(
            {
                "step_id": step_id,
                "global_id": global_id,
                "ifc_class": ifc_class,
                "name": name,
                "tag": tag,
                "type_name": type_name,
                "storey": storey,
                "issues": ", ".join(sorted({i.message for i in issues})),
                "issue_count": len(issues),
            }
        )

    return counts, rows


def _cap_rows(rows: List[Dict], max_rows: int) -> List[Dict]:
    if max_rows is None:
        return rows
    try:
        max_rows_i = int(max_rows)
    except Exception:
        max_rows_i = 2000

    if max_rows_i <= 0:
        return rows
    return rows[:max_rows_i]


def _style_cell(value, issue_count: int):
    if issue_count <= 0:
        return value
    return TableCell(value, background_color=Color(255, 230, 230))


