class Parametrization(vkt.Parametrization):
    model = vkt.Section("IFC input")
    model.intro = vkt.Text(
        textwrap.dedent(
            """\
            # Naming Convention Check (IFC)

            Upload an IFC file and scan element **Name**, **Tag** (optional), and **Type assignment** to flag:
            - Empty names
            - Default / placeholder names (e.g. `Wall#1`, `Unnamed`)
            - Missing numbering (optional rule)
            - Missing type assignment

            Use the tables to export a CSV and enforce naming standards consistently.
            """
        )
    )
    model.ifc = vkt.FileField("Upload IFC (.ifc or .ifczip)")
    model.scan_scope = vkt.OptionField(
        "Scan scope",
        options=["IfcProduct", "IfcObject", "IfcRoot"],
        default="IfcProduct",
        description="IfcProduct is recommended (physical + spatial).",
    )
    model.include_types = vkt.BooleanField(
        "Include IfcTypeObject entities in scan",
        default=False,
        description="If enabled, type objects themselves are also checked for naming.",
    )
    model.only_flagged = vkt.BooleanField(
        "Show only elements with issues (recommended)",
        default=True,
    )
    model.max_rows = vkt.NumberField(
        "Max rows per table",
        default=2000,
        min=100,
        max=50000,
        step=100,
        description="Large IFCs can contain many elements; this caps table size (summary always uses full scan).",
    )

    rules = vkt.Section("Naming rules")
    rules.intro = vkt.Text(
        textwrap.dedent(
            r"""\
            ## Rules

            - **Forbidden names**: comma-separated list checked case-insensitively by default.
            - **Default name regex**: if a name matches this regex it will be flagged as a default placeholder.
            - **Required naming pattern**: optional regex; if set, names that do not match will be flagged.

            Regex is evaluated with Python's `re`.
            """
        )
    )
    rules.forbidden_values = vkt.TextField(
        "Forbidden names (comma-separated)",
        default="Unnamed, Default",
    )
    rules.default_name_regex = vkt.TextField(
        "Default name regex (optional)",
        default=r"^\s*([A-Za-z][A-Za-z0-9 _\-]*)\s*#\s*\d+\s*$",
        description="Example matches 'Wall #1', 'Door#12'. Leave empty to disable user regex (built-in checks still run).",
    )
    rules.required_name_regex = vkt.TextField(
        "Required naming pattern (optional regex)",
        default="",
        description="Example: ^[A-Z]{2}-[A-Z0-9]+-\\d{3}$",
    )
    rules.case_sensitive = vkt.BooleanField("Regex case sensitive", default=False)

    rules.require_number_in_name = vkt.BooleanField(
        "Require a number in Name",
        default=True,
        description="Flags names without digits (helps enforce numbering; disable if your standard is purely descriptive).",
    )
    rules.check_tag_as_numbering = vkt.BooleanField(
        "Also check Tag as numbering field",
        default=False,
        description="If enabled, missing/unnumbered Tag is flagged (common when Tag is used as asset/mark number).",
    )


class Controller(vkt.Controller):
    label = "Naming Convention Check"
    parametrization = Parametrization

    @vkt.DataView("Summary", duration_guess=2)
    def summary_view(self, params, **kwargs):
        if not params.model.ifc:
            data = DataGroup(DataItem("Status", "Upload an IFC file to start."))
            return DataResult(data)

        try:
            counts, _rows = _analyze_ifc(params)
        except vkt.UserError:
            raise
        except Exception as e:
            raise vkt.UserError(f"Failed to read/scan IFC: {e}")

        flagged = counts["flagged"]
        checked = counts["checked"]
        status = DataStatus.SUCCESS if flagged == 0 else DataStatus.WARNING

        data = DataGroup(
            DataItem(
                "Scan result",
                f"{flagged} flagged out of {checked} checked",
                status=status,
                status_message="" if flagged == 0 else "Review the flagged elements table.",
            ),
            DataItem("Checked entities", checked),
            DataItem("Flagged entities", flagged),
            DataItem("Empty Name", counts["name_empty"]),
            DataItem("Default/placeholder Name", counts["name_default"]),
            DataItem("Forbidden Name", counts["name_forbidden"]),
            DataItem("Name without number", counts["name_no_number"]),
            DataItem("Missing Type assignment", counts["type_missing"]),
        )

        if bool(params.rules.check_tag_as_numbering):
            data.add(
                DataItem("Empty Tag", counts["tag_empty"]),
                DataItem("Tag without number", counts["tag_no_number"]),
            )

        return DataResult(data)

    @vkt.TableView("Flagged elements", duration_guess=2)
    def flagged_elements(self, params, **kwargs):
        if not params.model.ifc:
            return TableResult([], column_headers=["Info"])

        counts, rows = _analyze_ifc(params)
        flagged = [r for r in rows if r["issue_count"] > 0]

        max_rows = int(params.model.max_rows or 2000)
        flagged = _cap_rows(flagged, max_rows)

        data = []
        for idx, r in enumerate(flagged, start=1):
            c = r["issue_count"]
            data.append(
                [
                    idx,
                    r["step_id"],
                    r["global_id"],
                    r["ifc_class"],
                    _style_cell(r["name"], c),
                    _style_cell(r["tag"], c),
                    _style_cell(r["type_name"], c),
                    r["storey"],
                    _style_cell(r["issues"], c),
                ]
            )

        headers = [
            "#",
            "STEP id",
            "GlobalId",
            "IFC class",
            "Name",
            "Tag",
            "Type name",
            "Container (storey)",
            "Issues",
        ]
        return TableResult(data, column_headers=headers)

    @vkt.TableView("All checked elements", duration_guess=2)
    def all_elements(self, params, **kwargs):
        if not params.model.ifc:
            return TableResult([], column_headers=["Info"])

        _counts, rows = _analyze_ifc(params)

        if bool(params.model.only_flagged):
            rows = [r for r in rows if r["issue_count"] > 0]

        max_rows = int(params.model.max_rows or 2000)
        rows = _cap_rows(rows, max_rows)

        data = []
        for idx, r in enumerate(rows, start=1):
            c = r["issue_count"]
            data.append(
                [
                    idx,
                    r["step_id"],
                    r["global_id"],
                    r["ifc_class"],
                    _style_cell(r["name"], c),
                    _style_cell(r["tag"], c),
                    _style_cell(r["type_name"], c),
                    r["storey"],
                    _style_cell(r["issues"], c),
                ]
            )

        headers = [
            "#",
            "STEP id",
            "GlobalId",
            "IFC class",
            "Name",
            "Tag",
            "Type name",
            "Container (storey)",
            "Issues",
        ]
        return TableResult(data, column_headers=headers)

    @vkt.IFCView("IFC model", duration_guess=1, x_axis_to_right=True)
    def ifc_view(self, params, **kwargs):
        if not params.model.ifc:
            # IFCView can't show an empty result; guide user via error.
            raise vkt.UserError("Upload an IFC file to view the model.")
        return vkt.IFCResult(params.model.ifc.file)
